package com.ncdex.instrument.service;import com.ncdex.instrument.repository.InstrumentRepository;import com.ncdex.instrument.document.Instrument;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.data.redis.core.RedisTemplate;import org.springframework.data.redis.core.ValueOperations;import java.util.*;import java.time.Duration;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;@ExtendWith(MockitoExtension.class)class InstrumentServiceTest{@Mock InstrumentRepository repo;@Mock RedisTemplate<String,Object> redis;@Mock ValueOperations<String,Object> values;@InjectMocks InstrumentService service;@Test void cacheHitAvoidsMongoQuery(){Instrument i=new Instrument();when(redis.opsForValue()).thenReturn(values);when(values.get("instrument:GOLD-001")).thenReturn(i);assertSame(i,service.get("GOLD-001"));verify(repo,never()).findById(anyString());}@Test void cacheMissLoadsMongoAndCachesForFiveMinutes(){Instrument i=new Instrument();when(redis.opsForValue()).thenReturn(values);when(values.get("instrument:GOLD-001")).thenReturn(null);when(repo.findById("GOLD-001")).thenReturn(Optional.of(i));assertSame(i,service.get("GOLD-001"));verify(values).set("instrument:GOLD-001",i,Duration.ofMinutes(5));}@Test void missingInstrumentRaisesNotFound(){when(redis.opsForValue()).thenReturn(values);when(values.get("instrument:X")).thenReturn(null);when(repo.findById("X")).thenReturn(Optional.empty());assertThrows(NoSuchElementException.class,()->service.get("X"));}}
